import sys
from bisect import bisect_left

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    MAXN = 100000
    # 预处理每个数的真约数（不含自身），升序
    divs = [[] for _ in range(MAXN + 1)]
    for i in range(1, MAXN + 1):
        step = i
        j = i + step
        while j <= MAXN:
            divs[j].append(i)
            j += step

    def comb3(k: int) -> int:
        # 组合数 C(k, 3)
        return k * (k - 1) * (k - 2) // 6

    out_lines = []
    for _ in range(t):
        l = int(next(it))
        r = int(next(it))
        ans = 0
        for d in range(l, r + 1):
            arr = divs[d]
            # 统计位于 [l, d) 的约数个数
            p = bisect_left(arr, l)      # 第一个 >= l 的位置
            k = len(arr) - p
            if k >= 3:
                ans += comb3(k)
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

